package com.dreamfacilities.servlet;
import com.dreamfacilities.dao.FeedbackDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/feedbacks") public class FeedbackListServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{String search=q.getParameter("q");int rating=0;try{rating=Integer.parseInt(q.getParameter("rating"));}catch(Exception ignored){}try{FeedbackDAO d=new FeedbackDAO();q.setAttribute("feedbacks",d.find(search,rating,false));q.setAttribute("search",search==null?"":search);q.setAttribute("rating",rating);q.setAttribute("total",d.count());q.setAttribute("average",String.format(java.util.Locale.US,"%.1f",d.average()));}catch(Exception e){q.setAttribute("feedbacks",java.util.Collections.emptyList());q.setAttribute("error","Unable to load feedback. Check the database connection.");}q.getRequestDispatcher("/WEB-INF/views/feedbacks.jsp").forward(q,r);} }
